metrics.workdir_dsl:
workspace "Home Energy Management Platform" "C4 model of the home energy management platform" {

    configuration {
        scope "SoftwareSystem"
    }

    model {

        homeowner = person "Homeowner" "Uses the platform to manage the household's energy use and costs"

        energyManager = softwareSystem "Energy Manager" "Home energy management platform, owned and operated by our company" {
            dashboard = container "Dashboard Web App" "Where homeowners see consumption and costs" "Web Application"
            scheduler = container "Scheduling Service" "Plans charging and heating" "Service"
            ratesLibrary = container "Rates Library" "Computes energy prices from tariff and time of day" "Library"
            database = container "Database" "Stores meter readings and schedules" "Database"
        }

        smartMeterProvider = softwareSystem "Smart Meter Provider" "Provides live meter readings; operated by a different organization" "External"

        homeowner -> energyManager "Uses the platform to manage the household's energy use and costs" "HTTPS"
        energyManager -> smartMeterProvider "Fetches live meter readings" "HTTPS"
        homeowner -> dashboard "Views consumption and costs" "HTTPS"
        dashboard -> ratesLibrary "Embeds" "Embedded"
        scheduler -> ratesLibrary "Embeds" "Embedded"
        scheduler -> smartMeterProvider "Fetches live meter readings" "HTTPS"
        scheduler -> database "Stores meter readings and schedules" "SQL"
    }

    views {
        systemContext energyManager "SystemContext" "System context diagram for the Energy Manager" {
            include *
            autoLayout
        }

        container energyManager "Containers" "Container diagram for the Energy Manager" {
            include *
            autoLayout
        }
    }
}
